function pull(nodeName, label) {
  try {
    return $(nodeName).all().map(i => i.json).filter(j => j && j.title).map(j => ({
      title: (j.title || '').toString().trim(),
      link: (j.link || j.url || '').toString().trim(),
      snippet: (j.contentSnippet || j.content || j.description || '').toString().replace(/<[^>]*>/g, '').trim(),
      source: label,
      date: j.isoDate || j.pubDate || '',
    }));
  } catch (e) { return []; }
}

const normalized = [
  ...pull('Yahoo Finance', 'Yahoo Finance'),
  ...pull('CNBC', 'CNBC'),
  ...pull('MarketWatch', 'MarketWatch'),
  ...pull('Investing.com', 'Investing.com'),
];

// Deduplicate by normalized title
const seen = new Set();
const unique = [];
for (const n of normalized) {
  const key = n.title.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 60);
  if (key && !seen.has(key)) { seen.add(key); unique.push(n); }
}

// Sort newest first
unique.sort((a, b) => (Date.parse(b.date) || 0) - (Date.parse(a.date) || 0));

const top = unique.slice(0, 8);

const headlines = top.length
  ? top.map((n, idx) => `${idx + 1}. ${n.title} (${n.source})${n.snippet ? ' — ' + n.snippet : ''}`).join('\n')
  : 'No live headlines were available this hour.';

return [{ json: { headlines, newsItems: top } }];

const raw = ($input.first().json.text || '').toString();

// ---------- Parse labeled sections from the model output ----------
function grab(label) {
  const re = new RegExp(label + '\\s*:?\\s*([\\s\\S]*?)(?=\\n\\s*(?:TITLE|MARKET|TIP|CONCEPT|QUOTE|ACTION)\\s*:|$)', 'i');
  const m = raw.match(re);
  return m ? m[1].trim() : '';
}

const title   = grab('TITLE')   || 'Your Hourly Money Boost';
const market  = grab('MARKET');
const tip     = grab('TIP')     || raw;
const concept = grab('CONCEPT');
const quote   = grab('QUOTE');
const action  = grab('ACTION');

// ---------- Live news items from the RSS summary node ----------
let news = [];
try { news = $('Summarize Headlines').first().json.newsItems || []; } catch (e) { news = []; }
news = news.slice(0, 4);

// Glass-chip numbered news rows
const newsHtml = news.map((n, i) => `
  <tr>
    <td style="padding:0 0 ${i === news.length - 1 ? '0' : '16px'} 0;${i === news.length - 1 ? '' : 'border-bottom:1px solid rgba(255,255,255,0.10);'}padding-bottom:16px;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
        <tr>
          <td width="40" valign="top">
            <table role="presentation" cellpadding="0" cellspacing="0">
              <tr><td width="30" height="30" align="center" valign="middle" style="background:rgba(52,211,153,0.14);border:1px solid rgba(52,211,153,0.45);border-radius:50%;color:#34d399;font-size:13px;font-weight:700;font-family:'Inter',Arial,sans-serif;">
                ${i + 1}
              </td></tr>
            </table>
          </td>
          <td valign="top">
            <a href="${n.link}" style="color:#f1f5f9;text-decoration:none;font-size:15.5px;font-weight:600;line-height:1.45;display:block;font-family:'Inter',Arial,sans-serif;">${n.title}</a>
            ${n.snippet ? `<div style="color:#94a3b8;font-size:13.5px;line-height:1.55;margin-top:5px;font-family:'Inter',Arial,sans-serif;">${n.snippet}</div>` : ''}
            <div style="margin-top:8px;font-family:'Inter',Arial,sans-serif;font-size:12px;">
              <span style="color:#5eead4;font-weight:600;">${n.source}</span>
              <span style="color:#475569;"> &nbsp;•&nbsp; </span>
              <a href="${n.link}" style="color:#fbbf24;font-weight:600;text-decoration:none;">Read Full Story →</a>
            </div>
          </td>
        </tr>
      </table>
    </td>
  </tr>`).join('');

// ---------- Date / greeting ----------
const now = new Date();
const dateStr = now.toLocaleString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit' });

// ---------- Reusable glass primitives ----------
// Frosted "glass" card: translucent fill + soft border + sheen line on top.
// backdrop-filter blurs whatever sits behind it in clients that support it (Apple Mail, iOS/macOS Mail, newer webmail);
// everywhere else it degrades gracefully to a flat tinted panel over the dark gradient — still reads as "glass".
function glassCard(contentHtml, accent = 'rgba(255,255,255,0.14)') {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0">
    <tr><td style="background:rgba(255,255,255,0.055);border:1px solid ${accent};border-radius:20px;padding:22px 24px;box-shadow:0 8px 30px rgba(0,0,0,0.35);">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:14px;"><tr><td style="height:1px;background:linear-gradient(90deg,rgba(255,255,255,0.5),rgba(255,255,255,0));font-size:0;line-height:0;">&nbsp;</td></tr></table>
      ${contentHtml}
    </td></tr>
  </table>`;
}

// Glass pill section label
function glassTag(color, glow, emoji, label) {
  return `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 0 14px 0;"><tr>
    <td style="background:rgba(255,255,255,0.06);border:1px solid ${color};border-radius:999px;padding:6px 16px;box-shadow:0 0 14px ${glow};">
      <span style="font-family:'Inter',Arial,sans-serif;font-weight:700;font-size:11.5px;letter-spacing:1.4px;text-transform:uppercase;color:${color};">${emoji}&nbsp; ${label}</span>
    </td>
  </tr></table>`;
}

const html = `<!DOCTYPE html>
