<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="color-scheme" content="dark">
<meta name="supported-color-schemes" content="dark">
<title>${title}</title>
<!--[if mso]>
<noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript>
<![endif]-->
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet">
</head>
<body style="margin:0;padding:0;background:#070d19;font-family:'Inter',Arial,sans-serif;">
  <!-- Preheader -->
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">
    ${tip.slice(0, 110)}
  </div>

  <!--[if mso]><table role="presentation" width="100%" bgcolor="#0b1220"><tr><td><![endif]-->
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#0b1220;background-image:radial-gradient(circle at 15% 8%, rgba(52,211,153,0.16) 0%, transparent 40%),radial-gradient(circle at 88% 18%, rgba(96,165,250,0.14) 0%, transparent 42%),linear-gradient(160deg,#070d19 0%,#0d1b30 45%,#0a2420 100%);padding:32px 12px;">
    <tr><td align="center">
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;">

        <!-- Header: glass panel with a faint uptrend chart line -->
        <tr><td style="padding-bottom:22px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
            <tr><td style="background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.16);border-radius:24px;padding:0;box-shadow:0 12px 40px rgba(0,0,0,0.4);overflow:hidden;">

              <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="height:1px;background:linear-gradient(90deg,rgba(255,255,255,0.55),rgba(255,255,255,0));font-size:0;line-height:0;">&nbsp;</td></tr></table>

              <!-- decorative chart line -->
              <div style="line-height:0;font-size:0;">
                <svg viewBox="0 0 600 70" width="100%" height="70" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
                  <defs>
                    <linearGradient id="g1" x1="0" y1="0" x2="1" y2="0">
                      <stop offset="0%" stop-color="#34d399" stop-opacity="0.05"/>
                      <stop offset="100%" stop-color="#34d399" stop-opacity="0.55"/>
                    </linearGradient>
                  </defs>
                  <polyline points="0,55 60,50 120,58 180,40 240,44 300,26 360,32 420,18 480,22 540,10 600,14" fill="none" stroke="url(#g1)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>
                </svg>
