              <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="padding:8px 32px 34px 32px;text-align:center;">
                <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 16px auto;"><tr>
                  <td style="background:rgba(52,211,153,0.12);border:1px solid rgba(52,211,153,0.4);border-radius:999px;padding:6px 18px;">
                    <span style="color:#5eead4;font-size:11px;font-weight:700;letter-spacing:2.5px;text-transform:uppercase;font-family:'Inter',Arial,sans-serif;">◆ Finexa AI</span>
                  </td>
                </tr></table>
                <div style="font-size:27px;color:#f8fafc;font-weight:800;line-height:1.3;font-family:'Inter',Arial,sans-serif;letter-spacing:-0.3px;">${title}</div>
                <div style="font-size:12.5px;color:#94a3b8;margin-top:12px;font-family:'Inter',Arial,sans-serif;">🕐 &nbsp;${dateStr}</div>
              </td></tr></table>

            </td></tr>
          </table>
        </td></tr>

        ${market ? `<tr><td style="padding-bottom:20px;">
          ${glassTag('#34d399', 'rgba(52,211,153,0.35)', '📈', 'Market Pulse')}
          ${glassCard(`<p style="color:#e2e8f0;font-size:15.5px;line-height:1.7;margin:0;font-family:'Inter',Arial,sans-serif;">${market}</p>`, 'rgba(52,211,153,0.22)')}
        </td></tr>` : ''}

        ${newsHtml ? `<tr><td style="padding-bottom:20px;">
          ${glassTag('#60a5fa', 'rgba(96,165,250,0.35)', '📰', 'In The News')}
          ${glassCard(`<table role="presentation" width="100%" cellpadding="0" cellspacing="0">${newsHtml}</table>`, 'rgba(96,165,250,0.22)')}
        </td></tr>` : ''}

        <!-- Tip of the hour -->
        <tr><td style="padding-bottom:20px;">
          ${glassTag('#fbbf24', 'rgba(251,191,36,0.35)', '💡', 'Tip Of The Hour')}
          ${glassCard(`<p style="color:#e2e8f0;font-size:15.5px;line-height:1.7;margin:0;font-family:'Inter',Arial,sans-serif;">${tip}</p>`, 'rgba(251,191,36,0.22)')}
        </td></tr>

        ${concept ? `<tr><td style="padding-bottom:20px;">
          ${glassTag('#a78bfa', 'rgba(167,139,250,0.35)', '📘', 'Concept Corner')}
