                <tr><td style="padding:13px 36px;">
                  <a href="#" style="display:inline-block;color:#f8fafc;font-size:14.5px;font-weight:700;text-decoration:none;letter-spacing:0.3px;font-family:'Inter',Arial,sans-serif;">
                    Open Finexa App →
                  </a>
                </td></tr>
              </table>
            </td></tr>
          </table>
        </td></tr>

        <!-- Footer glass panel -->
        <tr><td style="padding-bottom:30px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
            <tr><td style="background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.10);border-radius:18px;padding:20px 24px;text-align:center;">
              <p style="color:#64748b;font-size:12px;line-height:1.7;margin:0;font-family:'Inter',Arial,sans-serif;">
                You're receiving this because you subscribed to Finexa AI money tips.<br>
                News headlines via public RSS feeds. General educational information, not personalized financial advice.
              </p>
              <p style="margin:14px 0 0 0;">
                <a href="#" style="color:#fb7185;text-decoration:none;font-size:12px;font-weight:600;font-family:'Inter',Arial,sans-serif;">Unsubscribe</a>
                <span style="color:#334155;"> &nbsp;·&nbsp; </span>
                <a href="#" style="color:#60a5fa;text-decoration:none;font-size:12px;font-weight:600;font-family:'Inter',Arial,sans-serif;">Preferences</a>
              </p>
            </td></tr>
          </table>
        </td></tr>

      </table>
    </td></tr>
  </table>
  <!--[if mso]></td></tr></table><![endif]-->
</body>
</html>`;

return [{ json: { subject: title, html } }];
